package com.collegeerp.erp.academic.entity;
import com.collegeerp.erp.academic.enums.AttendanceStatus; import com.collegeerp.erp.common.entity.BaseAuditEntity; import com.collegeerp.erp.student.entity.StudentProfile; import jakarta.persistence.*;
@Entity @Table(name="attendance_records",uniqueConstraints=@UniqueConstraint(columnNames={"session_id","student_id"})) public class AttendanceRecord extends BaseAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="session_id") private AttendanceSession session; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id") private StudentProfile student; @Enumerated(EnumType.STRING) private AttendanceStatus status=AttendanceStatus.ABSENT; private String remarks; public Long getId(){return id;} public AttendanceSession getSession(){return session;} public void setSession(AttendanceSession v){session=v;} public StudentProfile getStudent(){return student;} public void setStudent(StudentProfile v){student=v;} public AttendanceStatus getStatus(){return status;} public void setStatus(AttendanceStatus v){status=v;} public String getRemarks(){return remarks;} public void setRemarks(String v){remarks=v;} }
